import Foundation
import IndooroNavigation
import IndooroModels
import XCTest
@testable import IndooroNavigation
@testable import IndooroNavigationCore

/// Files of `NavigationFixtures/synthetic/` (generated by `scripts/field/make_synthetic_walk.py`; NOT a measurement).
enum ComparisonFixtures {
    static let recordingName = "synthetic-testraum-2026-10-19-1.jsonl"

    static var directory: URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent() // IndooroPositioningCompareTests
            .deletingLastPathComponent() // Tests
            .deletingLastPathComponent() // indooro-EinkaeuferFinal
            .appendingPathComponent("NavigationFixtures/synthetic", isDirectory: true)
    }

    static func recordingText() throws -> String {
        try String(contentsOf: directory.appendingPathComponent(recordingName), encoding: .utf8)
    }

    static func layoutData() throws -> Data {
        try Data(contentsOf: directory.appendingPathComponent("layout-synthetic-testraum.json"))
    }

    static func layout() throws -> LayoutData {
        try PositioningComparison.decodeLayout(layoutData())
    }

    static func run(warmupSeconds: Double? = nil) async throws -> PositioningComparisonResult {
        try await PositioningComparison.run(
            recordingJSONL: recordingText(),
            layoutJSON: layoutData(),
            recordingName: recordingName,
            options: PositioningComparisonOptions(warmupSeconds: warmupSeconds)
        )
    }
}
